@extends('layouts.app') @section('title','Быстрая выдача') @section('content')<h1 class="h4">📷 Быстрая выдача: читатель → книга</h1><p class="text-secondary">Сканируйте билет читателя, затем экземпляр. Работает с USB/Bluetooth-сканером и ручным вводом.</p><div class="card card-body mb-3"><input id="scan" class="form-control form-control-lg" autofocus placeholder="Сканируйте код и Enter"><div id="state" class="mt-3">1. Ожидается читатель</div><input type="date" id="due" class="form-control mt-2" value="{{now()->addDays(14)->format('Y-m-d')}}"></div><button id="reset" class="btn btn-outline-secondary">Сбросить</button><script>let reader=null,copy=null;const inp=document.getElementById('scan'),st=document.getElementById('state');async function resolve(code){let r=await fetch('{{route('library.scan.resolve')}}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{csrf_token()}}'},body:JSON.stringify({code})});let x=await r.json();if(!r.ok)throw Error(x.error||'Ошибка');return x}async function issue(){let r=await fetch('{{route('library.quick.issue')}}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{csrf_token()}}'},body:JSON.stringify({reader_id:reader.id,copy_id:copy.id,due_on:document.getElementById('due').value})});if(!r.ok)throw Error('Не удалось выдать');st.innerHTML='✅ Выдано: '+copy.label+'<br>Читатель: '+reader.label;reader=copy=null}inp.addEventListener('keydown',async e=>{if(e.key!=='Enter')return;e.preventDefault();let code=inp.value.trim();inp.value='';try{let x=await resolve(code);if(!reader){if(x.type!=='reader')throw Error('Сначала сканируйте читательский билет');reader=x;st.textContent='Читатель: '+x.label+' · теперь сканируйте книгу';}else{if(x.type!=='copy')throw Error('Теперь нужен код экземпляра');if(x.status!=='available')throw Error('Экземпляр недоступен: '+x.status);copy=x;await issue();}}catch(err){st.textContent='⚠️ '+err.message}});document.getElementById('reset').onclick=()=>{reader=copy=null;st.textContent='1. Ожидается читатель';inp.focus()};</script>@endsection